DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
MOVEMENT_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL)
SPACES = " \t"


class ParseError(ValueError):
    """A mistake in a data file. ``line`` is the 1-based line number."""

    def __init__(self, line: int, reason: str):
        super().__init__(f"line {line}: {reason}")
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False, repr=False)


@dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]]
    line: int = field(default=0, compare=False, repr=False)


def content_lines(text: str) -> Iterator[Tuple[int, str]]:
    """Yield (line number, line) for every line that is not blank or a comment.

    Lines end only at LF or CRLF; ``str.splitlines`` is deliberately not used.
    """
    if text.startswith("\ufeff"):
        text = text[1:]
    pieces = text.split("\n")
    if pieces and pieces[-1] == "":
        pieces.pop()
    for number, line in enumerate(pieces, start=1):
        if line.endswith("\r"):
            line = line[:-1]
        stripped = line.strip(SPACES)
        if not stripped or stripped.startswith("#"):
            continue
        yield number, line


def parse_sku(text: str) -> Optional[str]:
    """Return the upper-case SKU, or None when ``text`` is not shaped like one."""
    if SKU_RE.fullmatch(text):
        return text.upper()
    return None


def parse_order_id(text: str) -> Optional[str]:
    if ORDER_ID_RE.fullmatch(text):
        return text.upper()
    return None


def parse_date(text: str) -> Optional[datetime.date]:
    match = DATE_RE.fullmatch(text)
    if not match:
        return None
    try:
        return datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        return None


def parse_catalog(text: str) -> Dict[str, Product]:
    """Parse ``catalog.txt`` into a dict of SKU to Product, in file order."""
    catalog: Dict[str, Product] = {}
    for number, line in content_lines(text):
        fields = [f.strip(SPACES) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, f"expected 4 or 5 fields separated by '|', found {len(fields)}")
        sku = parse_sku(fields[0])
        if sku is None:
            raise ParseError(number, f"bad SKU {fields[0]!r}")
        if sku in catalog:
            raise ParseError(number, f"duplicate SKU {sku}")
        name = fields[1]
        if not name:
            raise ParseError(number, "empty name")
        if not PRICE_RE.fullmatch(fields[2]):
            raise ParseError(number, f"bad price {fields[2]!r}")
        price = Decimal(fields[2]).quantize(Decimal("0.01"))
        if price < Decimal("0.01"):
            raise ParseError(number, f"price must be at least 0.01, got {fields[2]!r}")
        if not WHOLE_RE.fullmatch(fields[3]):
            raise ParseError(number, f"bad reorder level {fields[3]!r}")
        reorder = int(fields[3])
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if fields[4].isascii() is False or tax not in TAX_RATES:
                raise ParseError(number, f"bad tax {fields[4]!r} (use standard, reduced or zero)")
        catalog[sku] = Product(sku, name, price, reorder, tax)
    return catalog


def counting_order(movements: List[Movement]) -> List[Movement]:
    """Movements in the order they count: by date, same day in file order."""
    return sorted(movements, key=lambda m: m.date)


def first_below_zero(movements: List[Movement]) -> Optional[Movement]:
    """Return the first movement (in counting order) that takes stock below zero."""
    balance: Dict[str, int] = {}
    for move in counting_order(movements):
        balance[move.sku] = balance.get(move.sku, 0) + move.quantity
        if balance[move.sku] < 0:
            return move
    return None


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    """Parse ``movements.txt``; stock may never go below zero in counting order."""
    movements: List[Movement] = []
    for number, line in content_lines(text):
        match = MOVEMENT_RE.fullmatch(line.strip(SPACES))
        if not match:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku_text, qty_text, note = match.groups()
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, f"bad date {date_text!r}")
        sku = parse_sku(sku_text)
        if sku is None or sku not in catalog:
            raise ParseError(number, f"unknown SKU {sku_text!r}")
        if not SIGNED_RE.fullmatch(qty_text) or int(qty_text) == 0:
            raise ParseError(number, f"bad quantity {qty_text!r}")
        movements.append(Movement(date, sku, int(qty_text), (note or "").strip(SPACES), number))
    bad = first_below_zero(movements)
    if bad is not None:
        raise ParseError(bad.line, f"stock of {bad.sku} would go below zero")
    return movements


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    """Parse ``orders.txt`` into a list of orders, in file order."""
    orders: List[Order] = []
    seen = set()
    for number, line in content_lines(text):
        tokens = re.split(r"[ \t]+", line.strip(SPACES))
        if len(tokens) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        id_text, date_text, customer, lines_text = tokens
        order_id = parse_order_id(id_text)
        if order_id is None:
            raise ParseError(number, f"bad order number {id_text!r}")
        if order_id in seen:
            raise ParseError(number, f"duplicate order {order_id}")
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, f"bad date {date_text!r}")
        lines: List[Tuple[str, int]] = []
        skus = set()
        for pair in lines_text.split(","):
            parts = pair.split("*")
            if len(parts) != 2:
                raise ParseError(number, f"bad order line {pair!r} (use SKU*QUANTITY)")
            sku = parse_sku(parts[0])
            if sku is None or sku not in catalog:
                raise ParseError(number, f"unknown SKU {parts[0]!r}")
            if sku in skus:
                raise ParseError(number, f"SKU {sku} appears twice in the order")
            if not WHOLE_RE.fullmatch(parts[1]) or int(parts[1]) < 1:
                raise ParseError(number, f"bad quantity {parts[1]!r}")
            skus.add(sku)
            lines.append((sku, int(parts[1])))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, number))
    return orders

"""Pricing an order: volume discount, order discount, allocation and tax."""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from typing import Dict, Iterable, List, Tuple

from .parsing import TAX_RATES, Product

PENNY = Decimal("0.01")
ZERO = Decimal("0.00")
ORDER_DISCOUNT_THRESHOLD = Decimal("500.00")
ORDER_DISCOUNT_RATE = Decimal("0.03")


def money(value: Decimal) -> Decimal:
    """Round to the penny, halves up; never returns negative zero."""
    rounded = value.quantize(PENNY, rounding=ROUND_HALF_UP)
    return ZERO if rounded == 0 else rounded


def fmt(value: Decimal) -> str:
    """Two-decimal string; zero is always ``0.00``."""
    return f"{money(value):.2f}"


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def volume_rate(quantity: int) -> Decimal:
    if quantity >= 50:
        return Decimal("0.10")
    if quantity >= 10:
        return Decimal("0.05")
    return Decimal("0")


def allocate(pennies: int, weights: List[int]) -> List[int]:
    """Share ``pennies`` over ``weights`` by largest remainder (earlier first on ties)."""
    total = sum(weights)
    if pennies == 0 or total == 0:
        return [0] * len(weights)
    shares = []
    remainders = []
    for i, weight in enumerate(weights):
        share, remainder = divmod(pennies * weight, total)
        shares.append(share)
        remainders.append((-remainder, i))
    left = pennies - sum(shares)
    for _, i in sorted(remainders)[:left]:
        shares[i] += 1
    return shares


def price_lines(lines: Iterable[Tuple[str, int]], catalog: Dict[str, Product]) -> Quote:
    """Price ``(sku, quantity)`` pairs as described under *Prices*."""
    quote_lines: List[QuoteLine] = []
    for sku, quantity in lines:
        product = catalog[sku.upper()]
        unit = money(product.price)
        gross = money(unit * quantity)
        cut = money(gross * volume_rate(quantity))
        discount = money(-cut)
        quote_lines.append(QuoteLine(product.sku, quantity, unit, gross, discount, money(gross - cut)))
    subtotal = money(sum((line.net for line in quote_lines), ZERO))
    cut = ZERO
    if subtotal >= ORDER_DISCOUNT_THRESHOLD:
        cut = money(subtotal * ORDER_DISCOUNT_RATE)
    shares = allocate(int(cut * 100), [int(line.net * 100) for line in quote_lines])
    tax = ZERO
    for line, share in zip(quote_lines, shares):
        taxable = line.net - Decimal(share) / 100
        tax += money(taxable * TAX_RATES[catalog[line.sku].tax])
    tax = money(tax)
    order_discount = money(-cut)
    return Quote(quote_lines, subtotal, order_discount, tax, money(subtotal + order_discount + tax))


def price_order(order, catalog: Dict[str, Product]) -> Quote:
    """Price a whole order (anything with ``.lines`` of ``(sku, quantity)``)."""
    return price_lines(order.lines, catalog)

