        if move.date > date:
            lowest = balance if lowest is None else min(lowest, balance)
    if move_is_later_free(lowest):
        return balance
    return min(balance_on(sku, date, movements), lowest)


def move_is_later_free(lowest: Optional[int]) -> bool:
    return lowest is None


def balance_on(sku: str, date: datetime.date, movements: List[Movement]) -> int:
    return sum(m.quantity for m in movements if m.sku == sku and m.date <= date)


def fulfil_plan(order: Order, date: datetime.date, movements: List[Movement]) -> Dict[str, int]:
    """Units to ship now per order line."""
    shipped = shipped_so_far(order, movements)
    plan = {}
    for sku, quantity in order.lines:
        owed = quantity - shipped[sku]
        plan[sku] = min(owed, max(0, available_on(sku, date, movements)))
    return plan


def invoice_quote(order: Order, catalog: Dict[str, Product], movements: List[Movement]) -> Optional[Quote]:
    """Price what has shipped so far; None when nothing has."""
    shipped = shipped_so_far(order, movements)
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    if not lines:
        return None
    return price_lines(lines, catalog)


def report_rows(orders: List[Order], catalog: Dict[str, Product], movements: List[Movement]) -> List[dict]:
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, int(o.id[3:]), o.id)):
        shipped = shipped_so_far(order, movements)
        invoice = invoice_quote(order, catalog, movements)
        rows.append({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "status": order_status(order, shipped),
            "ordered": sum(q for _, q in order.lines),
            "shipped": sum(shipped.values()),
            "quoted": price_lines(order.lines, catalog).total,
            "invoiced": invoice.total if invoice else None,
        })
    return rows
